#!/usr/bin/env python3
"""Street Legends backend: Flake enemy-drop item (backend / Publish).

USER SPEC (exact): item name "Flake"; sells for $400 per oz; when
collected it goes into the player's item screen (inventory). Art is the
uploaded pink-bag white-powder image, embedded below as a data-URI
icon_url (the GitHub push tool cannot carry binary files, so no raw
GitHub URL is used; the uploaded file is JPEG data despite the .png
name, so the URI uses image/jpeg; if the client cannot render the data
URI, the row falls back to the shield icon and the item still functions).

READINGS (NOT the user's decisions - correctable):
- "1 - 15 fights" is read as a 1-in-15 chance EACH fight, following the
  user's own correction on Pills (where "1 - 6" meant 1-in-6 per fight,
  not a 1-to-6-fight gap). Flat ~6.7% roll on every standard battle
  victory, 1 oz when it lands, any enemy type. NOT an interval counter,
  NO random-gap counter. PvP and guild-raid victories have no loot path in the
  snapshot and are not hooked.
- Use: consumes 1 oz; for 60 seconds armor (defense) is 50% higher. A
  second use while active refreshes the 60s timer (no stacking). When
  the buff expires, armor returns to normal.
- Sell: $400 per oz, 1 oz per tap, from the item screen, no prompt.

Design notes (mirroring the Grass/Pills/Rock Candy patches; live /app may
differ, hence guards; this patch is STANDALONE - it never assumes prior
item code ran, but it IS order-tolerant of them: the pool exclusion
extends a pool line already modified by Grass, Pills, and/or Rock Candy):
- Inventory is player["inventory"], a list of item_id strings or dicts;
  Flake is stored as ONE stacked dict {"item_id": "flake",
  "qty": N, "unit": "oz", ...} rather than one entry per oz.
- Flake is added to ALL_ITEMS so the inventory-details endpoint
  returns it (items absent from ALL_ITEMS are invisible on the item
  screen). It is EXCLUDED from the generic random drop pool so it
  cannot double-drop.
- Buffs live in player["active_buffs"] as {type: "defense", percent,
  ...}. Flake reuses that system with an expires_at timestamp plus
  a large battles_remaining (10000) so the time expiry - not the
  per-battle decrement - is what ends it.
- ARMOR HOOK (why the damage site, not the stat): player_stats["defense"]
  feeds BOTH the enemy-damage line in battle_action AND the level-up
  growth (stats.defense * 1.05). Mutating player_stats would permanently
  inflate base defense on a level-up during the buff. So the patch
  computes a live multiplier (_fl_def_mult, expiry-checked, from the
  buff's percent) and boosts defense_val at exactly the enemy-damage
  site in battle_action. Level-up math stays unboosted. The game's
  incoming-damage formula is: enemy_damage = max(1, enemy_attack -
  defense_val // 2), halved again on defend, full enemy attack when
  defense_val <= 0 (broken armor). A Flake buff therefore turns a hit
  of max(1, atk - def//2) into max(1, atk - int(def*1.5)//2). NOTE: if
  armor is broken, effective defense is 0 and 0 x 1.5 is still 0, so
  Flake gives no benefit until the armor is repaired.
- Territory-boss, PvP, and guild-raid damage paths are NOT hooked (same
  scope as the drop: standard monster battles only).
- The generic sell endpoint pays value//2 and pops one whole entry, so
  it must NOT be used for Flake: dedicated use/sell endpoints below pay
  exactly $400/oz and decrement qty. The frontend hides the generic
  Sell/Equip buttons for Flake rows.
- RUN ORDER: Grass -> Pills -> Rock Candy -> Flake. This patch tolerates
  pool lines already modified by any subset of the prior three, but the
  prior patches use exact-match or narrower pool anchors and do NOT
  tolerate a flake-modified line: if Flake runs first, their pool parts
  print a WARNING and that item could double-drop from the generic pool.
"""
import re, sys
from pathlib import Path

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("/app")
SRV = ROOT / "backend/server.py"

FLAKE_URL = "data:image/jpeg;base64,"

CATALOG = '''
# FLAKE_ITEM_CATALOG: Flake enemy-drop item (see patch header for spec/readings).
ALL_ITEMS["flake"] = {
    "id": "flake", "name": "Flake", "category": "consumable",
    "description": "Bag of flake. Use: +50% armor for 60 seconds. Sells for $400 per oz.",
    "icon": "shield", "icon_url": ''' + '"' + FLAKE_URL + '"' + ''',
    "rarity": "common", "equipment_type": "consumable",
    "stats_bonus": {}, "level_requirement": 1, "value": 400,
}
'''

ROUTES = '''
# FLAKE_ITEM_USE / FLAKE_ITEM_SELL: dedicated Flake endpoints ($400/oz, 1 oz per sell tap).
@api_router.post("/players/{player_id}/flake/use")
async def use_flake(player_id: str):
    """Use 1 oz of Flake: +50% armor for 60 seconds (refreshes if active)."""
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    f_idx = None
    f_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "flake":
            f_idx, f_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "flake":
            f_idx, f_qty = _i, 1
            break
    if f_idx is None or f_qty < 1:
        raise HTTPException(status_code=400, detail="No Flake in inventory")
    if f_qty <= 1:
        inv.pop(f_idx)
    elif isinstance(inv[f_idx], dict):
        inv[f_idx]["qty"] = f_qty - 1
    else:
        inv.pop(f_idx)
    stats = player.get("stats", {})
    base_defense = stats.get("defense", 0)
    gain = int(base_defense * 0.5)
    boosted_defense = int(base_defense * 1.5)
    expiry = (datetime.utcnow() + timedelta(minutes=1)).isoformat()
    buffs = [b for b in player.get("active_buffs", []) if b.get("item_id") != "flake"]
    buffs.append({
        "id": "flake_" + str(uuid.uuid4())[:8], "item_id": "flake", "name": "Flake",
        "type": "defense", "amount": gain, "percent": 0.5,
        "battles_remaining": 10000, "expires_at": expiry, "icon": "shield",
    })
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv, "active_buffs": buffs}},
    )
    return {"message": "Flake used! +50% armor for 60 seconds.", "base_defense": base_defense,
            "boosted_defense": boosted_defense, "expires_at": expiry, "oz_left": f_qty - 1}


@api_router.post("/players/{player_id}/flake/sell")
async def sell_flake(player_id: str, qty: int = 1):
    """Sell Flake at $400 per oz."""
    if qty < 1:
        raise HTTPException(status_code=400, detail="Quantity must be at least 1")
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    f_idx = None
    f_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "flake":
            f_idx, f_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "flake":
            f_idx, f_qty = _i, 1
            break
    if f_idx is None or f_qty < qty:
        raise HTTPException(status_code=400, detail="Not enough Flake in inventory")
    if f_qty <= qty:
        inv.pop(f_idx)
        left = 0
    elif isinstance(inv[f_idx], dict):
        inv[f_idx]["qty"] = f_qty - qty
        left = f_qty - qty
    else:
        inv.pop(f_idx)
        left = 0
    gained = 400 * qty
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv}, "$inc": {"cash": gained}},
    )
    return {"message": f"Sold {qty} oz of Flake for ${gained}", "cash_gained": gained, "oz_left": left}

'''


def main():
    if not SRV.exists():
        print("FLAKE_ITEM_ERROR: backend/server.py not found (run from /app)")
        return 1
    src = SRV.read_text(errors="ignore")
    orig = src
    landed = []

    # 1. Catalog entry.
    if "FLAKE_ITEM_CATALOG" in src:
        print("FLAKE_ITEM_CATALOG_ALREADY_APPLIED"); landed.append("catalog")
    else:
        anchor = "# Apply icon URLs to all equipment items"
        fallback = "ALL_ITEMS.update(LEVEL_ACCESSORIES)"
        if anchor in src:
            src = src.replace(anchor, CATALOG.strip() + "\n\n" + anchor, 1)
            print("FLAKE_ITEM_CATALOG_OK"); landed.append("catalog")
        elif fallback in src:
            src = src.replace(fallback, fallback + "\n" + CATALOG.strip(), 1)
            print("FLAKE_ITEM_CATALOG_OK"); landed.append("catalog")
        else:
            print("WARNING: catalog anchor not found - Flake NOT added to ALL_ITEMS (item will be invisible on the item screen)")

    # 2. Exclude Flake from the generic random drop pool (no double-drop).
    #    Tolerates a pool line already modified by Grass, Pills, and/or Rock Candy.
    if 'item["id"] != "flake"' in src:
        print("FLAKE_ITEM_POOL_EXCLUDE_ALREADY_APPLIED"); landed.append("pool")
    else:
        pool_re = re.compile(r'if ((?:item\["id"\] != "[a-z_]+" and )*item\["level_requirement"\] <= enemy\["level"\] \+ 2)')
        m = pool_re.search(src)
        if m:
            src = src[:m.start(1)] + 'item["id"] != "flake" and ' + src[m.start(1):]
            print("FLAKE_ITEM_POOL_EXCLUDE_OK"); landed.append("pool")
        else:
            print("WARNING: generic drop-pool anchor not found - Flake may ALSO drop from the generic pool, so it could double-drop")

    # 3. Dedicated 1-in-15-per-fight drop on monster-battle victory.
    if "FLAKE_ITEM_DROP" in src:
        print("FLAKE_ITEM_DROP_ALREADY_APPLIED"); landed.append("drop")
    else:
        loot_at = src.find('combat_log.append(f"Loot drop: {dropped_item[\'name\']}!")')
        if loot_at == -1:
            print("WARNING: victory loot anchor not found - Flake drop NOT added (no defeat hook)")
        else:
            upd_at = src.find("# Update player stats", loot_at)
            if upd_at == -1:
                print("WARNING: victory update anchor not found - Flake drop NOT added (no defeat hook)")
            else:
                drop = ('            # FLAKE_ITEM_DROP: READING - 1-in-15 chance EACH fight (flat ~6.7% roll), 1 oz, any monster enemy.\n'
                        '            if random.random() < (1/15):\n'
                        '                _fl_inv = player.get("inventory", [])\n'
                        '                _fl_idx = next((i for i, _it in enumerate(_fl_inv) if isinstance(_it, dict) and _it.get("item_id") == "flake"), None)\n'
                        '                if _fl_idx is None:\n'
                        '                    _fl_inv.append({"item_id": "flake", "qty": 1, "unit": "oz", "durability": 100, "max_durability": 100})\n'
                        '                else:\n'
                        '                    _fl_inv[_fl_idx]["qty"] = _fl_inv[_fl_idx].get("qty", 1) + 1\n'
                        '                await db.players.update_one({"id": player["id"]}, {"$set": {"inventory": _fl_inv}})\n'
                        '                rewards["items"] = (rewards.get("items") or []) + ["flake"]\n'
                        '                combat_log.append("Loot drop: Flake (1 oz)!")\n'
                        )
                src = src[:upd_at] + drop + src[upd_at:]
                print("FLAKE_ITEM_DROP_OK"); landed.append("drop")

    # 4. Inventory-details qty/unit passthrough (shared with Grass/Pills/Rock Candy;
    #    whichever patch runs first adds it, the rest skip).
    if "FLAKE_ITEM_QTY" in src or "ROCK_CANDY_ITEM_QTY" in src or "PILLS_ITEM_QTY" in src or "GRASS_ITEM_QTY" in src:
        print("FLAKE_ITEM_QTY_ALREADY_APPLIED"); landed.append("qty")
    else:
        anchor = 'item_with_durability["inventory_index"] = idx'
        if anchor in src:
            add = ('\n            # FLAKE_ITEM_QTY / ROCK_CANDY_ITEM_QTY / PILLS_ITEM_QTY / GRASS_ITEM_QTY: pass stacked quantities through to the item screen.\n'
                   '            if inv_item.get("qty") is not None:\n'
                   '                item_with_durability["qty"] = inv_item["qty"]\n'
                   '            if inv_item.get("unit"):\n'
                   '                item_with_durability["unit"] = inv_item["unit"]')
            src = src.replace(anchor, anchor + add, 1)
            print("FLAKE_ITEM_QTY_OK"); landed.append("qty")
        else:
            print("WARNING: inventory-details anchor not found - oz count will NOT reach the item screen (Flake will show without a quantity)")

    # 5. Armor hook: live defense multiplier at the enemy-damage site in battle_action.
    #    (No start_battle sum is touched: this hook checks expiry itself.)
    if "FLAKE_ITEM_ARMOR" in src:
        print("FLAKE_ITEM_ARMOR_ALREADY_APPLIED"); landed.append("armor")
    else:
        stats_anchor = "player_stats = await get_effective_stats(player)"
        if stats_anchor not in src:
            print("WARNING: battle stats anchor not found - ARMOR HOOK NOT VERIFIED, need a live snippet of battle_action where player_stats is computed")
        else:
            flag = ('\n    # FLAKE_ITEM_ARMOR: a live Flake buff boosts defense by (1 + percent) for 60s.\n'
                    '    # Expiry-checked here; buffs without expires_at count. player_stats itself is NOT mutated\n'
                    '    # (it also feeds level-up defense growth, which must stay unboosted).\n'
                    '    _fl_now_iso = datetime.utcnow().isoformat()\n'
                    '    _fl_def_mult = 1.0\n'
                    '    for _fl_b in player.get("active_buffs", []):\n'
                    '        if _fl_b.get("type") == "defense" and _fl_b.get("item_id") == "flake":\n'
                    '            _fl_exp = _fl_b.get("expires_at")\n'
                    '            if (not _fl_exp) or (str(_fl_exp) >= _fl_now_iso):\n'
                    '                _fl_def_mult = max(_fl_def_mult, 1 + float(_fl_b.get("percent", 0.5)))')
            src = src.replace(stats_anchor, stats_anchor + flag, 1)
            ok = True
            def_old = '            defense_val = player_stats.get("defense", 0)'
            if def_old in src:
                src = src.replace(def_old,
                    def_old + '\n            if _fl_def_mult > 1.0:\n                defense_val = int(defense_val * _fl_def_mult)', 1)
            else:
                print("WARNING: enemy-damage defense anchor not found - incoming hits will NOT get the Flake reduction")
                ok = False
            if ok:
                print("FLAKE_ITEM_ARMOR_OK"); landed.append("armor")
            else:
                print("FLAKE_ITEM_ARMOR_PARTIAL: multiplier flag added but the damage site was missed")

    # 6. Use + sell endpoints.
    if "FLAKE_ITEM_USE" in src and "FLAKE_ITEM_SELL" in src:
        print("FLAKE_ITEM_ENDPOINTS_ALREADY_APPLIED"); landed.append("endpoints")
    else:
        inc = "app.include_router(api_router)"
        if inc in src and "datetime" in src and "timedelta" in src and "uuid" in src:
            src = src.replace(inc, ROUTES.strip() + "\n\n\n" + inc, 1)
            print("FLAKE_ITEM_ENDPOINTS_OK"); landed.append("endpoints")
        else:
            print("WARNING: router anchor or datetime/timedelta/uuid imports not found - Flake use/sell endpoints NOT added")

    if src == orig:
        print("FLAKE_ITEM_ALREADY_APPLIED")
        return 0
    try:
        compile(src, "server.py", "exec")
    except SyntaxError as e:
        print("FLAKE_ITEM_SYNTAX_FAIL: %s (file NOT written)" % e)
        return 1
    SRV.write_text(src)
    if len(landed) == 6:
        print("FLAKE_ITEM_OK")
    else:
        print("FLAKE_ITEM_PARTIAL: " + ",".join(landed))
    return 0

if __name__ == "__main__":
    sys.exit(main())
